alter table brand_claim_verification_runs drop constraint if exists brand_claim_verification_runs_rules_version_check;
alter table brand_claim_verification_runs add constraint brand_claim_verification_runs_rules_version_check check(rules_version in('brand-claim-verification.v1','brand-claim-verification.v2'));
create table evidence_gap_routing_snapshots(id uuid not null,tenant_id uuid not null,rules_version text not null check(rules_version='evidence-gap-routing.v1'),input_sha256 char(64) not null,status text not null check(status='completed'),source_finding_count integer not null check(source_finding_count>=0),cluster_count integer not null check(cluster_count>=0),clusters jsonb not null check(jsonb_typeof(clusters)='array'),created_at timestamptz not null,primary key(tenant_id,id),unique(tenant_id,input_sha256));
create trigger evidence_gap_routing_snapshots_append_only before update or delete on evidence_gap_routing_snapshots for each row execute function reject_immutable_mutation();create trigger evidence_gap_routing_snapshots_no_truncate before truncate on evidence_gap_routing_snapshots for each statement execute function reject_immutable_mutation();alter table evidence_gap_routing_snapshots enable row level security;alter table evidence_gap_routing_snapshots force row level security;create policy evidence_gap_routing_snapshots_tenant_isolation on evidence_gap_routing_snapshots using(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid) with check(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
